const raw = $input.first().json.stdout || '';
const low = raw.toLowerCase();

const checks = {
  service: !/(inactive|failed|dead)/.test(low),
  config: !/(error loading services|failed to load config)/.test(low),
  dns: !/(nxdomain|servfail|no servers could be reached|connection timed out)/.test(low),
  replication: !/(replication.*failed|failed.*replication|error.*replication|consecutive failures)/.test(low),
  sysvol: !low.includes('sysvol_directory=missing'),
  database: !/(dbcheck.*failed|database.*error|error.*database)/.test(low),
  time: !/(clock skew|unsynchronized)/.test(low)
};

const failedChecks = Object.keys(checks).filter(k => !checks[k]);

let status = 'HEALTHY';
if (failedChecks.length >= 2) status = 'CRITICAL';
else if (failedChecks.length === 1) status = 'WARNING';

const guidance = {
  service: 'Check samba/samba-ad-dc service status and journal logs.',
  config: 'Run testparm -s and correct smb.conf configuration errors.',
  dns: 'Verify AD DNS, resolver configuration, and LDAP/Kerberos SRV records.',
  replication: 'Run samba-tool drs showrepl and investigate the failed replication partner.',
  sysvol: 'Verify SYSVOL and NETLOGON shares and GPO/SYSVOL replication.',
  database: 'Review samba-tool dbcheck output before performing any database repair.',
  time: 'Verify chrony/NTP synchronization on all domain controllers.'
};

const actions = failedChecks.map(x => guidance[x] || `Investigate ${x}.`);

return [{
  json: {
    timestamp: new Date().toISOString(),
    host: raw.match(/HOST=(.*)/)?.[1]?.trim() || 'unknown',
    status,
    failed_checks: failedChecks,
    checks,
    incident_required: status !== 'HEALTHY',
    priority: status === 'CRITICAL' ? 'P1' : status === 'WARNING' ? 'P2' : 'P4',
    recommended_actions: actions,
    raw_output: raw
  }
}];

const j = $input.first().json;
return [{
  json: {
    ...j,
    incident_type: 'SAMBA4_ACTIVE_DIRECTORY_HEALTH',
    alert_subject: `[${j.priority}] Samba4 AD Health - ${j.host}`,
    alert_body:
      `Samba4 Active Directory health issue detected.\n\n` +
      `Host: ${j.host}\n` +
      `Status: ${j.status}\n` +
      `Priority: ${j.priority}\n` +
      `Failed Checks: ${(j.failed_checks || []).join(', ') || 'None'}\n\n` +
      `Recommended Actions:\n${(j.recommended_actions || []).map(x => '- ' + x).join('\n')}`
  }
}];

const j = $input.first().json;
return [{
  json: {
    monitoring_status: 'HEALTHY',
    timestamp: j.timestamp,
    host: j.host,
    message: 'Samba4 Active Directory health checks passed.',
    checks: j.checks
  }
}];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

